  ('araucaria-angustifolia', 'Araucaria angustifolia', 'Araucaria angustifolia', 'Paraná pine', NULL, 'Conífera majestuosa de Sudamérica, de crecimiento lento y gran valor paisajístico y ecológico.', 'Conífera monumental sudamericana de porte único', 'Sus semillas eran un alimento básico de pueblos indígenas y su recolección marcaba ciclos sociales y rituales.', 28, NULL, 3, '0,8L', '2023', 600, 'Araucariaceae', 'tree', 'intermediate', 'rare', 'Medio', '30-40m', '8-12m', 'BR', 'Sur de Brasil', 'Bosques montanos subtropicales', ARRAY['9a', '9b', '10a']::text[], ARRAY['atlantico', 'subtropical']::text[], ARRAY['sol']::text[], ARRAY['exterior', 'colección']::text[], -8, 'medium', 'medium', '["Suelo profundo drenado","Riego regular joven","Pleno sol","Evitar caliza"]'::jsonb, '["Piñones comestibles","Longeva","En peligro"]'::jsonb, '{"soil":"ácido-drenado","wind":"media","growth":"medio"}'::jsonb, ARRAY['https://upload.wikimedia.org/wikipedia/commons/thumb/1/1d/Auraucaria_angsmall1.jpg/1280px-Auraucaria_angsmall1.jpg', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Arauc%C3%A1ria_da_serra_ga%C3%BAcha.jpg/1280px-Arauc%C3%A1ria_da_serra_ga%C3%BAcha.jpg', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/84/Itaimbezinho_-_Parque_Nacional_Aparados_da_Serra_33.JPG/2560px-Itaimbezinho_-_Parque_Nacional_Aparados_da_Serra_33.JPG', 'https://suehs.netlify.app/project/araucaria/featured_hu442460516f9ba3207d9db1b23058bc3e_1113678_720x0_resize_q90_lanczos.jpg']::text[], 'Ejemplar joven de Araucaria angustifolia con porte cónico y hojas rígidas en verticilos', 'https://www.argentinaforestal.com/2019/11/04/araucaria-angustifolia-un-gigante-de-la-selva-misionera-que-se-encuentra-bajo-una-iniciativa-de-manejo-conservacion-y-mejora-en-el-inta/', 'Araucaria angustifolia: conífera monumental', 'Conífera sudamericana de gran porte y copa en candelabro, ideal para jardines amplios y colecciones.', true, false),
  ('archontophoenix-cunninghamiana', 'Archontophoenix cunninghamiana', 'Archontophoenix cunninghamiana', 'Bangalow palm', NULL, 'Palmera elegante y de rápido crecimiento, con tronco liso y copa plumosa, muy usada en climas templados y subtropicales.', 'Palmera elegante y de rápido crecimiento', 'En algunos países se considera invasora por su alta capacidad de germinación en riberas.', 16, NULL, 3, '1L', '2024', 700, 'Arecaceae', 'palm', 'intermediate', 'uncommon', 'Rápido', '20-25m', '4-6m', 'AU', 'Queensland/NSW', 'Bosques húmedos y riberas', ARRAY['9b', '10a', '10b']::text[], ARRAY['atlantico', 'subtropical']::text[], ARRAY['sol', 'semisol']::text[], ARRAY['exterior', 'colección']::text[], -3, 'high', 'high', '["Suelo fértil","Riego frecuente","Proteger heladas","Evitar sequía"]'::jsonb, '["Crecimiento rápido","Muy ornamental"]'::jsonb, '{"soil":"fértil-húmedo","wind":"baja","salt":"baja"}'::jsonb, ARRAY['https://inaturalist-open-data.s3.amazonaws.com/photos/558874792/original.jpg', 'https://www.plantswhitsunday.com.au/wp-content/uploads/2020/03/Archontophoenix-Cunninghamiana.jpg', 'https://upload.wikimedia.org/wikipedia/commons/c/c0/Archontophoenix_cunninghamiana_-_Pillnitz.jpg', 'https://www.palmerasyjardines.com/wp-content/uploads/2019/01/100384.jpg']::text[], 'Plántula de Archontophoenix cunninghamiana con hojas pinnadas verdes y crecimiento vertical', 'https://www.palmpedia.net/wiki/Archontophoenix_cunninghamiana', 'Archontophoenix cunninghamiana, palmera elegante', 'Palmera de crecimiento rápido y tronco liso, perfecta para climas suaves con humedad.', true, false),
  ('bentinckia-condapanna', 'Bentinckia condapanna', 'Burretiokentia condapanna', 'Hill areca nut', NULL, 'Palmera alta y esbelta del sur de la India, adaptada a climas montanos húmedos.', 'Palmera alta tropical de montaña', 'Crece de forma natural en pendientes muy pronunciadas, donde pocas palmeras sobreviven.', 55, NULL, 1, '0,8L', '2025', 600, 'Arecaceae', 'palm', 'advanced', 'rare', 'Medio', '15-20m', '3-5m', 'IN', 'Ghats Occidentales', 'Bosques montanos húmedos', ARRAY['10a', '10b']::text[], ARRAY['tropical', 'montano']::text[], ARRAY['semisol']::text[], ARRAY['exterior', 'colección']::text[], 5, 'high', 'high', '["Humedad constante","Suelo profundo","Sombra ligera joven"]'::jsonb, '["Palmera montana","Muy poco común"]'::jsonb, '{"soil":"profundo-húmedo","wind":"media","growth":"medio"}'::jsonb, ARRAY['https://en.wikipedia.org/wiki/File:Bentinckia_condapanna_with_fruits.jpg', 'https://palmpedia.net/wiki/images/thumb/6/6f/B._condapanna3.jpg/248px-B._condapanna3.jpg', 'https://www.palmtalk.org/forum/uploads/monthly_2016_09/P1030440.jpg.4aebd10403fc1c9ac0e3599fb3567c1c.jpg', 'https://www.floribunda.xyz/wp-content/uploads/2019/02/bencon.jpg']::text[], 'Palmera Bentinckia condapanna joven con hojas largas y elegantes en semisombra', 'https://palmpedia.net/wiki/Bentinckia_condapanna', 'Bentinckia condapanna, palmera montana', 'Palmera tropical de montaña que requiere humedad ambiental y temperaturas suaves.', true, false),
  ('burretiokentia-hapala', 'Burretiokentia hapala', 'Burretiokentia hapala', NULL, NULL, 'Palmera rara de Nueva Caledonia, de crecimiento lento y gran interés para coleccionistas.', 'Palmera rara de Nueva Caledonia', 'Forma parte de un linaje de palmeras casi exclusivo de Nueva Caledonia.', 50, NULL, 4, '0,8L', '2025', 600, 'Arecaceae', 'palm', 'expert', 'extremely_rare', 'Lento', '8-12m', '3-4m', 'NC', 'Nueva Caledonia', 'Bosques húmedos y laderas', ARRAY['10a', '10b']::text[], ARRAY['tropical']::text[], ARRAY['semisol']::text[], ARRAY['exterior', 'colección']::text[], 4, 'medium', 'medium', '["Suelo drenado","Riego moderado","Evitar frío prolongado"]'::jsonb, '["Endémica NC","Rara en cultivo"]'::jsonb, '{"soil":"drenado","wind":"media","growth":"lento"}'::jsonb, ARRAY['https://www.palmtalk.org/forum/uploads/monthly_2019_01/65DD3B39-C231-46BA-AA56-90492CE4C2F2.jpeg.652a0cbf61114f5728e070d707eeaf91.jpeg', 'https://www.monaconatureencyclopedia.com/wp-content/uploads/2016/06/b-212-2_burretiokentia_hapala.jpg', 'https://dasignsourcebotanicals.com/wp-content/uploads/Burretiokentia-hapala-394x600.jpg', 'https://static.wixstatic.com/media/5010a8_25c2547441b4481988175d9065992761~mv2.jpg/v1/fit/w_500,h_500,q_90/file.jpg']::text[], 'Palmera rara Burretiokentia hapala en maceta mostrando follaje fino y porte esbelto', 'https://www.monaconatureencyclopedia.com/burretiokentia-hapala-2/?lang=es', 'Burretiokentia hapala, rareza de colección', 'Palmera endémica de Nueva Caledonia, de cultivo delicado y muy apreciada.', true, false),
  ('caryota-mitis', 'Caryota mitis', 'Caryota mitis', 'Fishtail palm', NULL, 'Palmera multicaul de hojas bipinnadas en forma de cola de pez, de rápido crecimiento en climas cálidos.', 'Palmera tropical de hojas en forma de cola de pez', 'Puede florecer durante varios años antes de que el tallo muera definitivamente.', 12, NULL, 2, '0,8L', '2024', 600, 'Arecaceae', 'palm', 'intermediate', 'common', 'Rápido', '10-15m', '4-6m', 'TH', 'Sudeste asiático', 'Selvas húmedas', ARRAY['10a', '10b', '11']::text[], ARRAY['tropical']::text[], ARRAY['semisol']::text[], ARRAY['exterior', 'interior', 'colección']::text[], 5, 'high', 'high', '["Riego alto","Suelo rico","Evitar frío","Semisombra"]'::jsonb, '["Hojas “cola de pez”","Tallos monocárpicos"]'::jsonb, '{"soil":"rico-húmedo","habit":"multicaul","growth":"rápido"}'::jsonb, ARRAY['https://www.palmerasyjardines.com/wp-content/uploads/2019/01/100430.jpg', 'https://www.palmerasyjardines.com/wp-content/uploads/2019/01/100427.jpg', 'https://upload.wikimedia.org/wikipedia/commons/9/99/Caryota_mitis_leaves.jpg', 'https://www.palmpedia.net/wiki/images/thumb/2/28/Cmfa3b28.jpg/400px-Cmfa3b28.jpg']::text[], 'Caryota mitis joven con hojas bipinnadas en forma de cola de pez', 'https://www.oxygenatwork.com/en/post/caryota-mitis-1', 'Caryota mitis, palmera cola de pez', 'Palmera tropical multicaul de hojas tipo cola de pez; perfecta para ambientes cálidos y húmedos.', true, false),
  ('ceratozamia-hildae', 'Ceratozamia hildae', 'Ceratozamia hildae', NULL, NULL, 'Cícada mexicana de crecimiento lento, muy apreciada por su follaje rígido y aspecto prehistórico.', 'Cícada mexicana de crecimiento lento', 'Fue descrita científicamente en el siglo XX, a pesar de su aspecto “prehistórico”.', 65, NULL, 1, '0,8L', '2022', 600, 'Arecaceae', 'cycad', 'advanced', 'very_rare', 'Lento', '1-2m', '1-2m', 'MX', 'Querétaro/Sierra Gorda', 'Bosques subtropicales', ARRAY['10a', '10b']::text[], ARRAY['subtropical']::text[], ARRAY['semisol']::text[], ARRAY['exterior', 'colección']::text[], 2, 'medium', 'medium', '["Semisombra","Suelo drenado","Riego moderado","Crecimiento lento"]'::jsonb, '["Cícada longeva","Aspecto prehistórico"]'::jsonb, '{"soil":"drenado","growth":"lento","pot":"apta"}'::jsonb, ARRAY['https://www.monaconatureencyclopedia.com/wp-content/uploads/2020/01/4-Ceratozamia-hildae.jpg', 'https://upload.wikimedia.org/wikipedia/commons/4/4f/Ceratozamia_Hildae_Leave.jpg', 'https://www.smgrowers.com/imagedb/Ceratozamia_hildae.jpg', 'https://bihrmann.com/caudiciforms/DIFO/cer-hil-lef.jpg']::text[], 'Ceratozamia hildae en maceta con hojas rígidas y aspecto prehistórico', 'https://www.monaconatureencyclopedia.com/ceratozamia-hildae/?lang=es', 'Ceratozamia hildae, cícada mexicana rara', 'Cícada de colección, muy longeva y de crecimiento lento; ideal en semisombra con drenaje.', true, false),
  ('chamaedorea-elegans-negrita', 'Chamaedorea elegans', 'Chamaedorea elegans', 'Palma de salón', '"Negrita"', 'Palmera compacta y resistente, ideal para interior o semisombra, muy popular como ornamental.', 'Palmera compacta ideal para interior', 'Fue una de las primeras palmeras exportadas masivamente a Europa en el siglo XIX.', 15, NULL, 3, '0,8L', '2025', 600, 'Arecaceae', 'palm', 'beginner', 'common', 'Lento', '2-3m', '1-2m', 'MX', 'Veracruz/Chiapas', 'Sotobosque tropical', ARRAY['10a', '10b']::text[], ARRAY['interior', 'tropical']::text[], ARRAY['semisombra', 'sombra']::text[], ARRAY['interior', 'exterior', 'colección']::text[], 5, 'medium', 'medium', '["Sombra luminosa","Riego moderado","Evitar sol fuerte"]'::jsonb, '["Muy usada en interior","Resistente"]'::jsonb, '{"soil":"ligero","light":"interior","growth":"lento"}'::jsonb, ARRAY['https://i.etsystatic.com/14485351/r/il/80bf19/3465580180/il_fullxfull.3465580180_mklv.jpg', 'https://static.wixstatic.com/media/0f7c58_af924c46b39a4dea90e970f352abb4e2.jpg/v1/fill/w_520,h_578,al_c,q_80,usm_0.66_1.00_0.01,enc_avif,quality_auto/0f7c58_af924c46b39a4dea90e970f352abb4e2.jpg', 'https://www.palmtalk.org/forum/uploads/monthly_2026_01/IMG_8313.thumb.jpeg.4629688e7cdf16edacb55b28fb3a81fd.jpeg', 'https://www.palmtalk.org/forum/uploads/monthly_2017_07/5967efec4cd88_Chamaedoreaelegansfront01.jpg.c36ef348a2315a9579168fc6c7f0fe36.jpg']::text[], 'Chamaedorea elegans joven con follaje fino y compacto ideal para interior', 'https://www.picturethisai.com/es/wiki/Chamaedorea_elegans__Negrita_.html', 'Chamaedorea elegans, palma de salón', 'Palmera compacta para interior o semisombra, fácil y muy decorativa.', true, false),
  ('chamaedorea-microspadix', 'Chamaedorea microspadix', 'Chamaedorea microspadix', 'Palma bambú', NULL, 'Palmera cespitosa de hojas finas, resistente al frío moderado y apta para sombra luminosa.', 'Palmera resistente para sombra', 'Produce frutos rojos muy decorativos que atraen fauna en su hábitat natural.', 18, NULL, 3, '0,8L', '2024', 600, 'Arecaceae', 'palm', 'intermediate', 'uncommon', 'Medio', '3-4m', '1-2m', 'MX', 'Sierra Madre', 'Bosques montanos', ARRAY['8b', '9a', '9b']::text[], ARRAY['atlantico', 'subtropical']::text[], ARRAY['semisombra']::text[], ARRAY['exterior', 'colección']::text[], -6, 'medium', 'medium', '["Semisombra","Suelo húmedo","Tolera frío moderado"]'::jsonb, '["Buena para climas suaves","Frutos rojos"]'::jsonb, '{"soil":"húmedo","cold":"alta","habit":"multicaul"}'::jsonb, NULL, 'Palmera Chamaedorea microspadix con hojas verdes estrechas y porte cespitoso', 'https://www.argentinat.org/taxa/206171-Chamaedorea-microspadix', 'Chamaedorea microspadix resistente', 'Palmera de sombra con buena tolerancia al frío moderado, ideal para jardines templados.', true, false),
  ('chamaedorea-radicalis', 'Chamaedorea radicalis', 'Chamaedorea radicalis', NULL, NULL, 'Palmera pequeña y muy rústica, capaz de tolerar temperaturas bajas y condiciones variables.', 'Palmera rústica tolerante al frío', 'Puede florecer incluso sin desarrollar un tronco visible.', 18, NULL, 4, '0,8L', '2024', 600, 'Arecaceae', 'palm', 'intermediate', 'uncommon', 'Medio', '2-4m', '1-2m', 'MX', 'Nuevo León/Tamaulipas', 'Laderas y bosques secos-subhúmedos', ARRAY['8a', '8b', '9a']::text[], ARRAY['atlantico', 'subtropical']::text[], ARRAY['sol', 'semisol']::text[], ARRAY['exterior', 'colección']::text[], -9, 'medium', 'medium', '["Suelo drenado","Riego moderado","Tolera frío"]'::jsonb, '["Muy rústica","Versátil"]'::jsonb, '{"soil":"drenado","cold":"muy alta","growth":"medio"}'::jsonb, NULL, 'Chamaedorea radicalis joven mostrando hojas firmes y crecimiento robusto', 'https://identify.plantnet.org/es/k-world-flora/species/Chamaedorea%20radicalis%20Mart./data', 'Chamaedorea radicalis rústica', 'Palmera compacta y muy rústica, tolera frío y se adapta bien con riego moderado.', true, false),
  ('chamaedorea-tepejilote', 'Chamaedorea tepejilote', 'Chamaedorea tepejilote', 'Tepejilote', NULL, 'Palmera tropical de sotobosque, conocida también por su uso tradicional alimentario en Mesoamérica.', 'Palmera tropical de sotobosque', 'Sus inflorescencias aún se consumen como manjar estacional en mercados locales.', 18, NULL, 3, '0,8L', '2024', 600, 'Arecaceae', 'palm', 'advanced', 'uncommon', 'Medio', '4-6m', '2-3m', 'GT', 'Centroamérica', 'Selva húmeda', ARRAY['10a', '10b']::text[], ARRAY['tropical']::text[], ARRAY['sombra', 'semisombra']::text[], ARRAY['exterior', 'colección']::text[], 6, 'high', 'high', '["Sombra","Humedad alta","Suelo rico","Riego frecuente"]'::jsonb, '["Uso alimentario tradicional"]'::jsonb, '{"soil":"rico-húmedo","light":"sombra","growth":"medio"}'::jsonb, NULL, 'Chamaedorea tepejilote joven de sotobosque con hojas amplias y verdes', 'https://www.inecol.mx/index.php/divulgacion/ciencia-hoy/tepejilote-maiz-de-montana-una-palma-asombrosa', 'Chamaedorea tepejilote tropical', 'Palmera de sotobosque tropical; requiere humedad constante y sombra.', true, false),
  ('chambeyronia-lepidota-mid-elevation', 'Chambeyronia lepidota', 'Chambeyronia lepidota', NULL, '"Mid elevation"', 'Palmera ornamental muy valorada por su follaje elegante y brotes jóvenes decorativos.', 'Palmera ornamental de follaje elegante', 'Está emparentada con especies famosas por sus hojas jóvenes de colores intensos.', 45, NULL, 1, '0,8L', '2024', 600, 'Arecaceae', 'palm', 'advanced', 'rare', 'Medio', '12-18m', '4-6m', 'NC', 'Nueva Caledonia', 'Bosques húmedos', ARRAY['10a', '10b']::text[], ARRAY['subtropical', 'tropical']::text[], ARRAY['semisol']::text[], ARRAY['exterior', 'colección']::text[], 0, 'medium', 'medium', '["Suelo drenado","Riego moderado","Clima suave"]'::jsonb, '["Brotes jóvenes llamativos"]'::jsonb, '{"soil":"drenado","feature":"brotes color","growth":"medio"}'::jsonb, NULL, 'Palmera Chambeyronia lepidota joven con follaje ornamental brillante', 'https://www.palmpedia.net/wiki/Chambeyronia_lepidota', 'Chambeyronia lepidota, palmera ornamental', 'Palmera de colección de follaje elegante, ideal en semisol con riego regular.', true, false),
  ('cyphophoenix-nucele', 'Cyphophoenix nucele', 'Cyphophoenix nucele', 'Lifou palm', NULL, 'Palmera endémica de Nueva Caledonia, de gran valor ornamental y crecimiento lento.', 'Palmera rara endémica de Nueva Caledonia', 'Su nombre hace referencia a la textura escamosa de sus semillas.', 64, NULL, 1, '0,8L', '2025', 600, 'Arecaceae', 'palm', 'expert', 'extremely_rare', 'Lento', '10-15m', '3-5m', 'NC', 'Islas Loyauté', 'Bosques insulares', ARRAY['10a', '10b']::text[], ARRAY['tropical']::text[], ARRAY['semisol']::text[], ARRAY['exterior', 'colección']::text[], 3, 'medium', 'medium', '["Suelo drenado","Humedad ambiental","Evitar frío"]'::jsonb, '["Endémica","Muy rara"]'::jsonb, '{"soil":"drenado","growth":"lento","salt":"media"}'::jsonb, NULL, 'Cyphophoenix nucele joven en maceta con hojas elegantes y estructura limpia', 'https://palmpedia.net/wiki/Cyphophoenix_nucele', 'Cyphophoenix nucele, rareza NC', 'Palmera endémica muy rara, de crecimiento lento y gran valor ornamental.', true, false),
  ('dictyocaryum-lamarckianum', 'Dictyocaryum lamarckianum', 'Dictyosperma lamarckianum', NULL, NULL, 'Palmera palmera tropical elegante, de tronco esbelto y hojas pinnadas arqueadas. Muy apreciada en jardinería, prospera en climas cálidos y húmedos, especialmente costeros.', 'Palmera tropical esbelta y muy ornamental', 'Fue nombrada en honor a Lamarck, uno de los pioneros de la botánica evolutiva.', 55, NULL, 1, '0,8L', '2025', 600, 'Arecaceae', 'palm', 'advanced', 'very_rare', 'Medio', '12-20m', '3-5m', 'MU', 'Mascareñas', 'Bosques húmedos oceánicos', ARRAY['10a', '10b']::text[], ARRAY['tropical', 'oceanico']::text[], ARRAY['semisol']::text[], ARRAY['exterior', 'colección']::text[], 2, 'high', 'high', '["Humedad alta","Viento protegido","Suelo profundo"]'::jsonb, '["Porte muy elegante","Insular"]'::jsonb, '{"soil":"profundo-húmedo","wind":"baja","growth":"medio"}'::jsonb, NULL, 'Dictyocaryum lamarckianum joven con tronco fino y hojas arqueadas', 'https://www.naturalista.uy/taxa/365207-Dictyocaryum-lamarckianum', 'Dictyocaryum lamarckianum esbelta', 'Palmera oceánica muy ornamental; prefiere humedad constante y abrigo del viento.', true, false),
